def parse_ini(text):
    """Parse INI text into section dictionaries, retaining multiline values."""
    sections = {}
    section = ""
    previous_key = None

    for number, raw in enumerate(text.split("\n"), start=1):
        line = raw.strip()
        if not line or line.startswith(("#", ";")):
            continue

        if line.startswith("[") and line.endswith("]"):
            section = line[1:-1].strip()
            if not section:
                raise ValueError(f"empty section name on line {number}")
            sections.setdefault(section, {})
            previous_key = None
        elif raw.startswith((" ", "\t")):
            if previous_key is None:
                raise ValueError(f"continuation without a key on line {number}")
            sections[section][previous_key] += "\n" + line
        else:
            key, separator, value = line.partition("=")
            if not separator:
                raise ValueError(f"missing '=' on line {number}")
            key = key.strip().lower()
            if not key:
                raise ValueError(f"empty key on line {number}")
            sections.setdefault(section, {})[key] = value.strip()
            previous_key = key

    return sections
